CREATE TABLE "EmployeePayrollBatch" ("id" TEXT NOT NULL, "month" TEXT NOT NULL, "status" "PayrollBatchStatus" NOT NULL DEFAULT 'DRAFT', "submittedAt" TIMESTAMP(3), "approvedAt" TIMESTAMP(3), "approvedBy" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "EmployeePayrollBatch_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "EmployeePayrollBatch_month_key" ON "EmployeePayrollBatch"("month");
CREATE TABLE "EmployeePayrollLine" ("id" TEXT NOT NULL, "batchId" TEXT NOT NULL, "employeeId" TEXT NOT NULL, "totalWorkingDays" INTEGER NOT NULL, "daysWorked" INTEGER NOT NULL, "leaveDays" INTEGER NOT NULL, "fixedSalary" DECIMAL(12,2) NOT NULL, "variablePercent" DECIMAL(5,2) NOT NULL DEFAULT 0, "variableAmount" DECIMAL(12,2) NOT NULL DEFAULT 0, "additionalPayment" DECIMAL(12,2) NOT NULL DEFAULT 0, "variablePay" DECIMAL(12,2) NOT NULL, "totalPayable" DECIMAL(12,2) NOT NULL, CONSTRAINT "EmployeePayrollLine_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "EmployeePayrollLine_batchId_employeeId_key" ON "EmployeePayrollLine"("batchId", "employeeId");
ALTER TABLE "EmployeePayrollLine" ADD CONSTRAINT "EmployeePayrollLine_batchId_fkey" FOREIGN KEY ("batchId") REFERENCES "EmployeePayrollBatch"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "EmployeePayrollLine" ADD CONSTRAINT "EmployeePayrollLine_employeeId_fkey" FOREIGN KEY ("employeeId") REFERENCES "Employee"("id") ON DELETE CASCADE ON UPDATE CASCADE;
